('courses', '1790395720627671', $irr${"assign": {}, "categoryId": 1790748591706286, "color": "#0071e3", "desc": "This is designed to give hospitality professionals all the tools they need to build customer connections and to stay cool under pressure.\n\nThe goal of this course is to promote and build upon the warm and inclusive service culture.", "image": "data:image/jpeg;base64,", "learnerIds": [], "mandatory": false, "pos": 0, "status": "published", "test": {"passMark": 80, "questions": [{"answer": 0, "options": ["Caring about the customer's experience", "Serving every order as fast as possible", "Explaining the coffee's origin to every guest", "Offering regulars a discount"], "q": "According to the course, what is the starting point for giving great hospitality?"}, {"answer": 1, "options": ["Rudeness is now against the law", "Specialty coffee shops are easy to find, so an unhappy customer can simply go elsewhere", "Customers now know more about coffee than baristas", "Coffee has become too expensive for customers to tolerate it"], "q": "Why can a café no longer get away with being rude to customers, as some baristas did in the early 2000s?"}, {"answer": 2, "options": ["Latte art skills", "Single estate sourcing", "Community-building and positive human interactions", "Speed of service"], "q": "What does the author now believe matters more than coffee flavour?"}, {"answer": 3, "options": ["Its menu and prices", "Its location and interior design", "The equipment it uses", "The values within the café: the practices, habits and decisions of the people in it"], "q": "A café's culture is based on…"}, {"answer": 0, "options": ["That they have been noticed and you're ready to serve", "That they should wait to be called", "That you are busy and will get to them later", "That they need to join the queue"], "q": "What should anyone near the café (outside, at the door or at the bar) feel from your first glance?"}, {"answer": 1, "options": ["Only greet the person at the front of the queue", "You owe something to everyone waiting, but keep greetings brief", "Skip greetings until the rush is over", "Give each guest a long, personal greeting"], "q": "There's a queue at a busy time. What does the course say about greeting guests?"}, {"answer": 2, "options": ["Ask whether they've visited before", "Serve them quickly without a greeting", "Treat them as new, because this interaction can decide whether they become a regular", "Wait for a colleague who might know them"], "q": "You don't recognise a customer. How should you treat them?"}, {"answer": 3, "options": ["Every time they order", "Only if they ask for a filter coffee", "At the start of every conversation", "When the guest shows interest, and a little at a time over several visits"], "q": "When should you share coffee knowledge with a guest?"}, {"answer": 0, "options": ["Admit you don't know", "Give your best guess so you seem knowledgeable", "Change the subject", "Tell them it doesn't matter"], "q": "A guest asks a coffee question you can't answer with confidence. What should you do?"}, {"answer": 1, "options": ["Point out what went wrong with it", "Simply say thank you", "Offer to pour it again", "Tell them it's usually much better"], "q": "A guest praises your latte art, but you're not happy with the pour. What's the best response?"}, {"answer": 2, "options": ["An attack on your skills", "Something to pass straight to the manager", "A gift, and much better than a bad online review you can't answer", "A sign the guest will never return"], "q": "How does the course describe a complaint made to your face?"}, {"answer": 3, "options": ["A refund and nothing else", "The same drink again", "An explanation of why it tastes that way", "A different, stronger-tasting drink such as a long black"], "q": "A guest finds their pour-over too weak, and a remake would come out exactly the same. What should you offer?"}, {"answer": 0, "options": ["Set personal boundaries as early as possible, with support from managers or HR", "Put up with it to keep them as a customer", "Give them a full explanation for saying no", "Stop serving them without saying anything"], "q": "A regular wants more personal attention than a staff member is comfortable with. What does the course advise?"}, {"answer": 1, "options": ["To win the argument", "To keep yourself, colleagues and other guests safe", "To make the guest apologise", "To get the guest to stop being angry at all costs"], "q": "When handling an aggressive guest, what is the goal?"}, {"answer": 2, "options": ["Stand close so they feel supported", "About arm's length", "About four times your usual distance", "No space; block their path to the counter"], "q": "How much space does the course suggest giving an agitated person?"}, {"answer": 3, "options": ["Speaking in a low, slow, even voice", "Offering them choices", "Giving them plenty of space", "Smiling at them"], "q": "Which of these should you AVOID when de-escalating an angry guest?"}, {"answer": 0, "options": ["Before or after service, when no guests are around", "In front of a waiting guest, so they learn in real conditions", "During the busiest period, to build speed", "Whenever the manager has a spare moment on the floor"], "q": "A new staff member needs to learn how to pour a pint. According to the course, when should this training happen?"}, {"answer": 1, "options": ["One", "Five", "Ten", "Two"], "q": "Madeleine Geach suggests about how many pieces of positive feedback for every criticism?"}, {"answer": 2, "options": ["Long conversations about the coffee", "Table service and a seated experience", "Fast, accurate service, since most guests don't want conversation", "Offering tasting flights"], "q": "What does good hospitality mean at a train station coffee kiosk?"}, {"answer": 3, "options": ["It needs bean-to-cup automation", "It only works in train stations", "It serves 400–600 drinks per machine per day", "A much higher staff cost per drink, in return for more time for warm, personal service"], "q": "What is the main trade-off of a brew bar (slow bar) service style?"}]}, "testAssigned": {}, "title": "Hospitality and Culture", "trainerIds": [], "validMonths": 0}$irr$::jsonb),
('courses', '1790750311941562', $irr${"categoryId": 1790395691778477, "color": "#0071e3", "desc": "Processing is the second course in a series on coffee origin. At harvest, this course covers how coffee is handled from ripe cherry until it's dried and ready to roast.\n\nProcessing affects the final cup as much as terroir does, and it's becoming a more creative and complex way to shape flavour.\nRegions used to be tied to one traditional method. Over the last decade that has changed. Farmers can now shape flavour to their liking, and buyers can pre-purchase the same producer's coffee processed several different ways. As a result, the range of coffee flavours has never been wider.\n\nThe three main methods:\nNatural (dry) process - the most common.\nWashed - a wet process that includes an intentional fermentation stage.\nPulped natural (\"honey\") - a wet process introduced to reduce the risk of over-fermentation seen in the washed and natural methods.\n\nWhat the course covers: All three methods in depth, plus the newest fermentation techniques used around the world.", "image": "data:image/jpeg;base64,", "learnerIds": [], "mandatory": false, "pos": 0, "status": "production", "title": "Coffee Processing", "trainerIds": [], "validMonths": 0, "assign": {}, "testAssigned": {}}$irr$::jsonb),
('courses', '1790752158804547', $irr${"categoryId": 1790751987233581, "color": "#30d158", "desc": "This course consists of recipe cards, descriptions and definitions of the Muro Lunch Menu", "image": "data:image/jpeg;base64,", "learnerIds": [], "mandatory": false, "pos": 0, "status": "published", "title": "Muro Lunch Menu", "trainerIds": [], "validMonths": 0, "assign": {}, "testAssigned": {}}$irr$::jsonb),
('courses', '1790754517104359', $irr${"assign": {}, "categoryId": 1790754220197839, "color": "#1d1d1f", "desc": "After this course: the trainer shall be able to independently train a new/existing employee to standard in any Training Module within this software.", "image": "data:image/jpeg;base64,", "learnerIds": [], "mandatory": false, "pos": 0, "status": "published", "test": {"passMark": 80, "questions": [{"answer": 1, "options": ["Getting the shift finished on time", "Building another person's skill until they can work to standard on their own", "Showing the trainee the quickest way to do things", "Making sure everyone likes them"], "q": "What is the main focus of a trainer?"}, {"answer": 2, "options": ["Let the new hire decide", "Ignore it, it isn't your job", "Teach the full standard and tell your manager about the concern", "Teach the new hire to skip it when it's quiet"], "q": "A colleague teaches a new hire to skip a required safety check “because it's quiet”. What should you do?"}, {"answer": 1, "options": ["Ask “Does that make sense?”", "Ask them to show you the task", "Assume they understood if they nod", "Give them a written summary"], "q": "Which is the best way to check that a trainee has understood?"}, {"answer": 3, "options": ["Watch, copy, repeat, finish", "Read, memorise, test, repeat", "Show, leave, return, sign off", "Tell, show, do, review"], "q": "What are the four steps of the learning cycle?"}, {"answer": 1, "options": ["Understand how to greet guests", "Greet every guest within the agreed time, introduce yourself and ask if it is their first visit", "Be friendly with guests", "Learn about service"], "q": "Which is the strongest training objective?"}, {"answer": 0, "options": ["Near the start", "At the end", "Only if there is time", "They are optional"], "q": "Where should safety and hygiene steps go in a task breakdown?"}, {"answer": 1, "options": ["Use as few images as possible", "Only include content the trainee needs to meet the objective", "Keep all modules under five minutes", "Remove all examples"], "q": "What does “no clutter” mean when building a module?"}, {"answer": 2, "options": ["Fast, cheap, short", "Long, detailed, complete", "Simple, visual, easy", "Formal, written, tested"], "q": "What are the three principles to check every module against?"}, {"answer": 1, "options": ["When the trainee has never done the task", "When the trainee knows the basics but is not yet consistent", "When the task is a safety standard they skipped", "On their first day"], "q": "When should you coach rather than teach?"}, {"answer": 2, "options": ["Show it once, quickly, and let them try", "Explain it verbally without showing", "Show it at full speed, then slowly step by step", "Let them try first, then show them"], "q": "When demonstrating a skill, what should you do first?"}, {"answer": 2, "options": ["“Good job today.”", "“You were careless.”", "“On table 6 you repeated the order back, so the kitchen got an accurate ticket. Keep doing that.”", "“You always forget things.”"], "q": "Which is an example of specific, useful feedback?"}, {"answer": 1, "options": ["Discuss it with the rest of the team", "Involve your manager", "Let it go to avoid conflict", "Tell them they will lose their job"], "q": "A trainee keeps ignoring a hygiene standard after you have discussed it and offered support. What should you do?"}, {"answer": 2, "options": ["When they have attended the session", "When they have done it once with your help", "When they can do it to standard, on their own, consistently", "When you run out of training time"], "q": "When should you sign off a lesson for a trainee?"}, {"answer": 1, "options": ["Your general impression of them", "Facts about what they did, against the checklist", "Only the mistakes", "Nothing, just remember it"], "q": "What should you record when observing a trainee?"}, {"answer": 2, "options": ["Upselling and extra product knowledge", "Speed during peak service", "Safety, hygiene and allergens", "Whatever is quickest to teach"], "q": "What should a new hire's training plan cover first?"}, {"answer": 1, "options": ["Each trainer uses their own method", "Teach from the SOP and the iTrain module, and use the same breakdowns", "Only the GM trains new staff", "Change the standard to suit each restaurant"], "q": "How do you keep training consistent across all four restaurants?"}, {"answer": 1, "options": ["Whenever they make any mistake", "Only for safety, hygiene or allergen risks", "Never, even for safety", "Every few minutes to give tips"], "q": "During the post-trial observation, when should you step in?"}, {"answer": 2, "options": ["The trainer", "The trainee", "The manager", "The team"], "q": "Who makes the final decision on the outcome of a trial?"}, {"answer": 1, "options": ["A written test only", "Observation and checking the finished result", "Asking if they feel confident", "Counting hours trained"], "q": "Which assessment method is best for checking a skill such as plating a dish?"}, {"answer": 3, "options": ["The pace", "The examples you use", "The amount of support", "The standard"], "q": "When adapting training to a trainee, what should never change?"}]}, "testAssigned": {}, "title": "Training the Team 101", "trainerIds": [], "validMonths": 0}$irr$::jsonb),
('courses', '1790777616358007', $irr${"assign": {}, "categoryId": 1790754220197839, "color": "#1f4e79", "desc": "Store Manager Development Session, Module 1.\n\nDriving business acumen is a logical, structured approach to problem solving, keeping the strategic intent in mind. This module builds critical thinking and structured problem solving, then works through the levers that drive a store’s business: labour, inventory, and the metrics behind ADT and average ticket.\n\nIt finishes with four case studies and two home assignments to put it all into practice.", "image": "data:image/jpeg;base64,", "learnerIds": [], "mandatory": false, "pos": 1, "status": "published", "test": {"passMark": 80, "questions": [{"answer": 3, "options": ["Strategic thinking", "Risk assessment", "Decision making", "Visual merchandising"], "q": "Which of these is NOT one of the capabilities critical thinking brings together?"}, {"answer": 0, "options": ["Developing the proper attitude", "Collecting every available report", "Agreeing with the majority view", "Choosing a framework"], "q": "What is the first step to becoming a proficient critical thinker?"}, {"answer": 1, "options": ["Act, Intake, Investigate", "Intake, Investigate, Act", "Investigate, Act, Intake", "Intake, Act, Investigate"], "q": "In what order does a critical thinker work through a problem?"}, {"answer": 2, "options": ["Reaching the one right answer", "Speed", "The method you use to derive your answer", "Using as many frameworks as possible"], "q": "When solving a business case, what matters most?"}, {"answer": 3, "options": ["Company & capacity", "Revenue & products", "Operations", "Costs"], "q": "In the “inside the business” structure, which area covers the allocation of overheads?"}, {"answer": 0, "options": ["To grow transactions", "To reduce costs only", "To cover absences", "To clean the store"], "q": "What is labour always used for, according to the module?"}, {"answer": 1, "options": ["4 PM to 7 PM", "3:30 PM to 7:30 PM", "2 PM to 6 PM", "5 PM to 9 PM"], "q": "If 4–7 PM is a store’s peak, when should maximum labour be available?"}, {"answer": 2, "options": ["Lowest stock at all times", "Order weekly without fail", "Right product, in the right place, at the right time to optimise sales and profit", "Full shelves regardless of sales"], "q": "What is the inventory management vision?"}, {"answer": 3, "options": ["One", "Three", "Four", "Two: point of use and point of stock"], "q": "In how many places at most should a product be stored?"}, {"answer": 0, "options": ["AT = APR × IPT", "AT = ADT × IPT", "AT = APR ÷ IPT", "AT = USD × APR"], "q": "Which formula gives the average ticket (AT)?"}, {"answer": 1, "options": ["IPT 1, AT Rs 150", "IPT 2, AT Rs 275", "IPT 2, AT Rs 137.5", "IPT 1, AT Rs 275"], "q": "A customer buys a beverage at Rs 150 and a food item at Rs 125. What are the IPT and AT?"}, {"answer": 2, "options": ["3 months", "6 months", "12 months", "24 months"], "q": "Revenue comp is only calculated for stores that are at least how old?"}, {"answer": 3, "options": ["75%", "33.3%", "57.1%", "42.85%"], "q": "A store has 6 part-time and 8 full-time baristas. What is its part-timer %?"}, {"answer": 0, "options": ["Rs 20,000", "Rs 30,000", "Rs 12,500", "Rs 40,000"], "q": "A store’s daily sales are Rs 50,000 and MSR tender is 40%. How much was paid by Starbucks Card?"}, {"answer": 1, "options": ["ADS = IPT × APR", "ADS = ADT × AT", "ADS = MSR × ADT", "ADS = Comps × AT"], "q": "How is average daily sales (ADS) built up in the key levers?"}]}, "testAssigned": {}, "title": "Ignite: Business Acumen", "trainerIds": [], "validMonths": 0}$irr$::jsonb),
