-- IRRLearning demo: run this once in Supabase (SQL Editor -> New query -> paste -> Run).
-- DEMO SECURITY: anyone with the site's address can read and change this data. Use demo data only.

create table if not exists public.docs (
  coll text not null,
  id text not null,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  primary key (coll, id)
);
alter table public.docs enable row level security;
drop policy if exists "demo: anyone can read and write" on public.docs;
create policy "demo: anyone can read and write" on public.docs
  for all to anon, authenticated using (true) with check (true);
grant select, insert, update, delete on public.docs to anon, authenticated;

-- Live updates between people using the site at the same time
do $$ begin
  alter publication supabase_realtime add table public.docs;
exception when duplicate_object then null; end $$;

-- Images and videos uploaded in lessons
  on conflict (id) do update set public = true;
drop policy if exists "demo: anyone can upload" on storage.objects;
create policy "demo: anyone can upload" on storage.objects
  for insert to anon, authenticated with check (bucket_id = 'uploads');

-- Course content (departments, categories, courses, chapters, lessons, tests)
on conflict (coll, id) do update set data = excluded.data, updated_at = now();
